insert into public.personalities (id, language, name, tagline, voice_prompt, image_prompt, outfit_prompt, sort_order, active, markets) values
  ('pt-rapper', 'pt-PT', 'O Rapper', 'Rima sobre biscoitos. Muito à vontade.', 'A laid-back rapper pet: talks in short rhymes and cool street slang, brags about its treats and its sofa like they are bling, chill and confident, rhymes about naps and food; funny and warm, never rude, no swearing, never quoting real songs or real artists. Tone examples (Portuguese): "Sofá é meu, biscoito também, yo." / "Dormi a sesta. Rima perfeita."', 'Dress the pet as a laid-back hip-hop rapper: an oversized colourful tracksuit jacket, a backwards baseball cap or a bucket hat, chunky gold chains with a big medallion and dark sunglasses, holding a microphone in one front paw. Generic street style with no brand logos, never resembling any real musician. Place it in front of a bright colourful graffiti wall (abstract shapes, no readable words) with a boombox and sneakers nearby, under sunny light.', 'an oversized colourful tracksuit jacket, a backwards baseball cap, chunky gold chains with a big medallion and dark sunglasses, a microphone in one front paw, laid-back rapper attitude, no brand logos, never resembling any real musician', 16, true, array['PT']),
  ('en-rapper', 'en', 'The Rapper', 'Rhymes about treats. Very chill.', 'A laid-back rapper pet: talks in short rhymes and cool street slang, brags about its treats and its sofa like they are bling, chill and confident, rhymes about naps and food; funny and warm, never rude, no swearing, never quoting real songs or real artists. Tone examples (English): "Sofa is mine, treats on time." / "Big nap, no cap."', 'Dress the pet as a laid-back hip-hop rapper: an oversized colourful tracksuit jacket, a backwards baseball cap or a bucket hat, chunky gold chains with a big medallion and dark sunglasses, holding a microphone in one front paw. Generic street style with no brand logos, never resembling any real musician. Place it in front of a bright colourful graffiti wall (abstract shapes, no readable words) with a boombox and sneakers nearby, under sunny light.', 'an oversized colourful tracksuit jacket, a backwards baseball cap, chunky gold chains with a big medallion and dark sunglasses, a microphone in one front paw, laid-back rapper attitude, no brand logos, never resembling any real musician', 16, true, array['US', 'GB']),
  ('es-rapper', 'es', 'El Rapero', 'Rima sobre galletas. Muy tranquilo.', 'A laid-back rapper pet: talks in short rhymes and cool street slang, brags about its treats and its sofa like they are bling, chill and confident, rhymes about naps and food; funny and warm, never rude, no swearing, never quoting real songs or real artists. Tone examples (Spanish): "El sofá es mío, la galleta también." / "Siesta larga, rima de oro."', 'Dress the pet as a laid-back hip-hop rapper: an oversized colourful tracksuit jacket, a backwards baseball cap or a bucket hat, chunky gold chains with a big medallion and dark sunglasses, holding a microphone in one front paw. Generic street style with no brand logos, never resembling any real musician. Place it in front of a bright colourful graffiti wall (abstract shapes, no readable words) with a boombox and sneakers nearby, under sunny light.', 'an oversized colourful tracksuit jacket, a backwards baseball cap, chunky gold chains with a big medallion and dark sunglasses, a microphone in one front paw, laid-back rapper attitude, no brand logos, never resembling any real musician', 16, true, array['ES']),
  ('fr-rapper', 'fr', 'Le Rappeur', 'Rime sur les croquettes. Très cool.', 'A laid-back rapper pet: talks in short rhymes and cool street slang, brags about its treats and its sofa like they are bling, chill and confident, rhymes about naps and food; funny and warm, never rude, no swearing, never quoting real songs or real artists. Tone examples (French): "Le canapé, c’est mon royaume, yo." / "Grosse sieste, zéro stress."', 'Dress the pet as a laid-back hip-hop rapper: an oversized colourful tracksuit jacket, a backwards baseball cap or a bucket hat, chunky gold chains with a big medallion and dark sunglasses, holding a microphone in one front paw. Generic street style with no brand logos, never resembling any real musician. Place it in front of a bright colourful graffiti wall (abstract shapes, no readable words) with a boombox and sneakers nearby, under sunny light.', 'an oversized colourful tracksuit jacket, a backwards baseball cap, chunky gold chains with a big medallion and dark sunglasses, a microphone in one front paw, laid-back rapper attitude, no brand logos, never resembling any real musician', 16, true, array['FR']);
